    "accept": `application/json`,
    "Content-Type": `application/json`,
    "x-api-key": `${process.env.LANGFLOW_API_KEY ?? ""}`,
  },
  body: JSON.stringify({
  "stop_component_id": "OpenAIModel-Uksag"
}),
};

fetch(url, options)
  .then(async (response) => {
    if (!response.ok) {
