    "Content-Type": `application/json`,
    "x-api-key": `${process.env.LANGFLOW_API_KEY ?? ""}`,
  },
  body: JSON.stringify({
  "data": {
    "nodes": [],
    "edges": []
  },
  "inputs": {
    "input_value": "Your custom input here",
    "session": "session_id"
  }
}),
};

fetch(url, options)
